const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const location1 = ee.Geometry.Point(136.025799, 33.710618); // (lon, lat)
  const location2 = ee.Geometry.Point(136.367495, 33.884848); // (lon, lat)
  const date = ee.Date('2018-09-15');
  const buffer_radius = 500; // Use a small buffer to get average around the point due to MODIS resolution

  // 2. Data Acquisition & Check
  const collection = ee.ImageCollection('MODIS/006/MOD09GA')
    .filterDate(date, date.advance(1, 'day'))
    .filterBounds(location1.buffer(buffer_radius).merge(location2.buffer(buffer_radius)));

  const size = await collection.size().getInfo();
  if (size === 0) {
    console.log("No MODIS Terra images found for 2018-09-15 in the specified locations.");
    console.log("C1");
    return;
  }

  const image = collection.first();

  // Function to mask clouds and non-water pixels
  // Turbidity is typically associated with increased reflectance in the blue/green bands over water.
  // We'll use the 'State_1km' band for cloud and water masking.
  function maskModisCloudsAndLand(img) {
    const qa = img.select('State_1km');

    // Bits 0-1: Cloud State (00: Clear, 01: Cloudy, 10: Mixed, 11: Not Set)
    const cloudState = qa.rightShift(0).clientAnd(3);
    const clearMask = cloudState.eq(0); // Only clear conditions

    // Bit 3: Cloud Shadow (0: No, 1: Yes)
    const cloudShadowMask = qa.rightShift(3).clientAnd(1).eq(0);

    // Bit 7: Water (0: No, 1: Yes)
    const waterMask = qa.rightShift(7).clientAnd(1).eq(1); // Only water pixels

    const combinedMask = clearMask.and(cloudShadowMask).and(waterMask);

    return img.updateMask(combinedMask);
  }

  // Apply masking
  const maskedImage = maskModisCloudsAndLand(image);

  // Select bands relevant for turbidity (Blue and Green reflectance)
  // 'sur_refl_b3' (Blue: 459-479 nm)
  // 'sur_refl_b4' (Green: 545-565 nm)
  // Higher reflectance in these bands generally indicates higher turbidity.
  // We'll take the average of Blue and Green reflectance as an indicator.
  const turbidityBand = maskedImage.expression(
    '(B3 + B4) / 2', {
      'B3': maskedImage.select('sur_refl_b3'),
      'B4': maskedImage.select('sur_refl_b4')
    }
  ).rename('turbidity_index');


  // 3. Processing & 4. Calculation
  const scale = 500; // MODIS resolution is 500m for these bands

  const reducer = ee.Reducer.mean().setOutputs(['mean_turbidity']);
  const pixelCountReducer = ee.Reducer.count().setOutputs(['pixel_count']);

  // Region 1 analysis
  const stats1 = await turbidityBand.reduceRegion({
    reducer: reducer.combine({ reducer2: pixelCountReducer, sharedInputs: true }),
    geometry: location1.buffer(buffer_radius),
    scale: scale,
    maxPixels: 1e9
  }).getInfo();

  const turbidity1 = stats1 ? stats1.mean_turbidity : null;
  const pixels1 = stats1 ? stats1.pixel_count : 0;

  // Region 2 analysis
  const stats2 = await turbidityBand.reduceRegion({
    reducer: reducer.combine({ reducer2: pixelCountReducer, sharedInputs: true }),
    geometry: location2.buffer(buffer_radius),
    scale: scale,
    maxPixels: 1e9
  }).getInfo();

  const turbidity2 = stats2 ? stats2.mean_turbidity : null;
  const pixels2 = stats2 ? stats2.pixel_count : 0;

  // 5. Validation & Final Answer
  if (pixels1 === 0 || pixels2 === 0) {
    console.log(`Location 1 Pixels: ${pixels1}, Location 2 Pixels: ${pixels2}`);
    console.log("No valid water pixels found after cloud/land masking for one or both locations.");
    console.log("C2");
    return;
  }

  if (turbidity1 === null || isNaN(turbidity1) || turbidity2 === null || isNaN(turbidity2)) {
    console.log(`Location 1 Turbidity: ${turbidity1}, Location 2 Turbidity: ${turbidity2}`);
    console.log("Calculation resulted in None/NaN for one or both turbidity values.");
    console.log("C3");
    return;
  }

  // MODIS reflectance values are scaled by 10000. Unscale for more readable output.
  const unscaledTurbidity1 = turbidity1 / 10000;
  const unscaledTurbidity2 = turbidity2 / 10000;

  console.log(`Location 1 Turbidity (avg Blue+Green Reflectance): ${unscaledTurbidity1.toFixed(4)} (Pixels: ${pixels1})`);
  console.log(`Location 2 Turbidity (avg Blue+Green Reflectance): ${unscaledTurbidity2.toFixed(4)} (Pixels: ${pixels2})`);

  if (unscaledTurbidity1 > unscaledTurbidity2) {
    console.log("A"); // Yes, there was more turbidity at location 1
  } else {
    console.log("B"); // No, there was not more turbidity at location 1
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
